--
-- Name: vista_abonos_por_venta; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_abonos_por_venta AS
 SELECT venta_id,
    count(*) FILTER (WHERE (estado <> 'ANULADO'::public.estado_abono)) AS cantidad_abonos,
    COALESCE(sum(monto) FILTER (WHERE (estado <> 'ANULADO'::public.estado_abono)), (0)::numeric) AS total_abonado,
    max(created_at) AS ultimo_abono
   FROM public.abonos a
  GROUP BY venta_id;


--
-- Name: vista_boletas_completas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_boletas_completas AS
 SELECT b.id,
    b.rifa_id,
    b.numero,
    b.estado,
    b.qr_url,
    b.barcode,
    b.bloqueo_hasta,
    b.created_at,
    r.nombre AS rifa_nombre,
    r.estado AS rifa_estado,
    r.precio_boleta,
    c.nombre AS cliente_nombre,
    c.telefono AS cliente_telefono,
    c.email AS cliente_email,
    u.nombre AS vendedor_nombre
   FROM (((public.boletas b
     JOIN public.rifas r ON ((b.rifa_id = r.id)))
     LEFT JOIN public.clientes c ON ((b.cliente_id = c.id)))
     LEFT JOIN public.usuarios u ON ((b.vendido_por = u.id)));


--
-- Name: vista_estadisticas_rifas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_estadisticas_rifas AS
 SELECT r.id,
    r.nombre,
    r.estado,
    r.precio_boleta,
    r.total_boletas,
    r.boletas_vendidas,
    r.boletas_disponibles,
    round((((r.boletas_vendidas)::numeric * 100.0) / (NULLIF(r.total_boletas, 0))::numeric), 2) AS porcentaje_vendido,
    COALESCE(sum(v.monto_total) FILTER (WHERE (v.estado_venta = 'PAGADA'::public.estado_venta)), (0)::numeric) AS ingresos_totales,
    COALESCE(sum(v.abono_total) FILTER (WHERE (v.estado_venta = 'PAGADA'::public.estado_venta)), (0)::numeric) AS abonos_totales,
    count(DISTINCT v.cliente_id) FILTER (WHERE (v.estado_venta = 'PAGADA'::public.estado_venta)) AS clientes_unicos,
    r.fecha_sorteo
   FROM (public.rifas r
     LEFT JOIN public.ventas v ON ((r.id = v.rifa_id)))
  GROUP BY r.id, r.nombre, r.estado, r.precio_boleta, r.total_boletas, r.boletas_vendidas, r.boletas_disponibles, r.fecha_sorteo;


