--
-- Name: vista_resumen_ventas _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.vista_resumen_ventas AS
 SELECT v.id,
    v.rifa_id,
    v.monto_total,
    v.abono_total,
    v.saldo_pendiente,
    v.estado_venta,
    v.es_venta_admin,
    v.es_venta_online,
    v.gateway_pago,
    v.referencia_pago,
    v.expires_at,
    v.created_at,
    r.nombre AS rifa_nombre,
    c.nombre AS cliente_nombre,
    c.telefono AS cliente_telefono,
    u.nombre AS vendedor_nombre,
    mp.nombre AS medio_pago_nombre,
    count(vd.boleta_id) AS cantidad_boletas
   FROM (((((public.ventas v
     JOIN public.rifas r ON ((v.rifa_id = r.id)))
     JOIN public.clientes c ON ((v.cliente_id = c.id)))
     LEFT JOIN public.usuarios u ON ((v.vendedor_id = u.id)))
     LEFT JOIN public.medios_pago mp ON ((v.medio_pago_id = mp.id)))
     LEFT JOIN public.venta_detalles vd ON ((v.id = vd.venta_id)))
  GROUP BY v.id, r.nombre, c.nombre, c.telefono, u.nombre, mp.nombre;


